// ASYNC

const execAsync = async (
		asyncFunc: () => void
		): Promise<unknown> => {

	return await asyncFunc()
}

// ---------------------------------------------------------------------------
// --- if passed an async function, will return a promise
//     in that case, you must use await

export const EXEC = (
		func: () => void
		): void => {

	try {
		if (isAsyncFunction(func)) {
			execAsync(func)
		}
		else {
			func()
		}
	}
	catch (err) {
		croak(`in EXEC(): ${getErrStr(err)}`)
	}
	return
}

