export const abbrevStr = (
		str: string,
		maxlen: number = 31
		): string => {

	const escaped = escd(str)
	const len = escaped.length
	if (len <= maxlen) {
		return escaped
	}
	const seglen = Math.trunc((maxlen-1) / 2)
	return (
		  escaped.substring(0, seglen)
		+ uni.ellipsis
		+ escaped.substring(len - seglen)
		)
}

